if (records.isEmpty()) return;
producer.beginTransaction();
try {
    for (ConsumerRecord<String, String> r : records)
        producer.send(new ProducerRecord<>("ledger-entries", r.key(), "entry:" + r.value()));
    Map<TopicPartition, OffsetAndMetadata> next = new HashMap<>();
    for (TopicPartition tp : records.partitions()) {
        List<ConsumerRecord<String, String>> rs = records.records(tp);
        next.put(tp, new OffsetAndMetadata(rs.get(rs.size() - 1).offset() + 1));
    }
    producer.sendOffsetsToTransaction(next, consumer.groupMetadata());
    producer.commitTransaction();
} catch (ProducerFencedException fenced) {
    throw fenced;                                        // close the producer: a newer one owns the id
} catch (KafkaException e) {
    producer.abortTransaction();
    for (TopicPartition tp : records.partitions())
        consumer.seek(tp, records.records(tp).get(0).offset());   // read the batch again
}

